const lessons7=rawLessons7.map(x=>({title:x[0],goal:x[1],theory:x[2],hook:x[3],facts:x[4],opts:[x[4][0]+' — тақырыптың негізгі ұғымы','Барлық ағза мен үдеріс бірдей болады','Тек атауын жаттау жеткілікті'],answer:0}));
let lessons=lessons8;
const badgeDefs=[['🔬','Алғашқы қадам',1],['🧬','Жасуша детективі',2],['⚗️','Bio хакер',4],['🌿','Тіршілік зерттеушісі',6],['🔥','Тұрақты ғалым',8],['🧠','Білім архитекторы',10],['🏆','Тоқсан шебері',15],['👑','BIO LEGEND',16]];
let currentUser=null,currentLesson=0,mood='',quizScore=null,selectedGrade=8;
function show(id){document.querySelectorAll('.page').forEach(x=>x.classList.remove('active'));$(id).classList.add('active');window.scrollTo({top:0,behavior:'smooth'});if(id==='teacher')renderTeacher();if(id==='lesson'&&lessons[currentLesson]){$('lessonNo').textContent=`${selectedGrade}-СЫНЫП • ${currentLesson+1}-САБАҚ`;$('videoLink').href='https://www.youtube.com/results?search_query='+encodeURIComponent(`${selectedGrade} сынып биология ${lessons[currentLesson].title}`);startLessonSession()}}
function goHome(){show('home')}
function updateHeader(){let logged=currentUser&&currentUser.role!=='teacher';$('guestActions').classList.toggle('hidden',logged);$('profileButton').classList.toggle('hidden',!logged);if(logged){$('profileAvatar').textContent=currentUser.avatar||'🧬';$('profileName').textContent=currentUser.name.split(' ')[0]}}
function startJourney(){currentUser?continueJourney():show('register')}
function showShowcase(){toast(currentUser?'Зертхана сенің маршрутыңда ашық!':'Алдымен зерттеуші профиліңді аш 🌱');currentUser?studentHome():show('register')}
function userGrade(){let n=parseInt(currentUser?.class);return n===7?7:8}
function setGrade(g){selectedGrade=g;lessons=g===7?lessons7:lessons8}
function openMyLessons(){if(!currentUser)return show('login');openGrade(userGrade())}
function openMyResults(){currentUser?studentHome():show('login')}
function gradeProgress(){let all=currentUser?.progress||{},p={};Object.entries(all).forEach(([k,v])=>{if(k.startsWith(selectedGrade+'-'))p[Number(k.split('-')[1])]=v;else if(selectedGrade===8&&/^\d+$/.test(k))p[Number(k)]=v});return p}
function openGrade(g){setGrade(g);$('gradeTitle').textContent=g+'-сынып';$('quarterGrid').innerHTML=[1,2,3,4].map(q=>{let ready=(g===7||g===8)&&q===1;return `<article class="quarter-card ${ready?'ready':''}" onclick="openQuarter(${q})"><span class="kicker">${q}-ТОҚСАН</span><b>${ready?'16 сабақ':'Жақында'}</b><p>${ready?'Ойындар, тәжірибелер және жеке прогресс':'Жаңа сабақтар әзірленуде'}</p><i>${ready?'→':'🔒'}</i></article>`}).join('');$('quarterLessons').innerHTML='';show('grade')}
function openQuarter(q){if(q!==1||(selectedGrade!==7&&selectedGrade!==8)){$('quarterLessons').innerHTML='<div class="dashboard-card"><h3>🌱 Бұл тоқсан әзірленіп жатыр</h3><p>Қазір 7 және 8-сыныптың 1-тоқсаны толық ашық.</p></div>';return}$('quarterLessons').innerHTML=`<div class="section-head"><div><span class="kicker">${selectedGrade}-СЫНЫП • 1-ТОҚСАН</span><h2>Менің сабақтарым</h2></div><p>Әр сабақ 150 XP береді. Келесі сабақтар ретімен ашылады.</p></div><div id="gradeLessons" class="route-list"></div>`;lessonCards('gradeLessons')}
function lessonCards(target){let el=$(target);if(!el)return;let p=gradeProgress(),count=Object.keys(p).length;el.innerHTML=lessons.map((l,i)=>{let done=!!p[i],locked=currentUser&&i>count;return `<article class="route-card ${done?'completed':''} ${locked?'locked-route':''}" onclick="${locked?`toast('Алдымен алдыңғы сабақты аяқта 🔒')`:`openLesson(${i})`}"><div class="route-node">${done?'✓':locked?'🔒':String(i+1).padStart(2,'0')}</div><div><small>${selectedGrade}-СЫНЫП • ${String(i+1).padStart(2,'0')}-САБАҚ</small><h3>${l.title}</h3><p>${l.goal}</p></div><span>${done?'Аяқталды':locked?'Құлыптаулы':'Бастау →'}</span></article>`}).join('')}
function localUsers(){try{return JSON.parse(localStorage.getItem('bioUsers')||'[]')}catch{return[]}} function saveUsers(us){localStorage.setItem('bioUsers',JSON.stringify(us))}
async function api(payload){if(!API_URL)return null;try{return await(await fetch(API_URL,{method:'POST',body:JSON.stringify(payload)})).json()}catch{return null}}
async function register(){let u={name:$('fullName').value.trim(),class:$('studentClass').value,user:$('regUser').value.trim(),pass:$('regPass').value,avatar:$('studentAvatar').value,role:'student',progress:{},created:new Date().toISOString()};if(!u.name||!u.user||!u.pass)return formMessage('regMsg','Барлық өрісті толтырыңыз','error');if(u.pass.length<4)return formMessage('regMsg','Құпиясөз кемінде 4 таңбадан тұрсын','error');let us=localUsers();if(us.some(x=>x.user.toLowerCase()===u.user.toLowerCase()))return formMessage('regMsg','Бұл логин бос емес','error');if(API_URL){let r=await api({action:'register',...u});if(!r?.ok)return formMessage('regMsg',r?.message||'Сервер қатесі','error')}us.push(u);saveUsers(us);currentUser=u;sessionStorage.setItem('bioCurrent',u.user);updateHeader();studentHome(true)}
async function login(){let user=$('loginUser').value.trim(),pass=$('loginPass').value;if(user==='teacher'&&pass==='bio2026'){currentUser={role:'teacher',name:'Мұғалім'};updateHeader();return show('teacher')}let u=localUsers().find(x=>x.user===user&&x.pass===pass);if(!u&&API_URL){let r=await api({action:'login',user,pass});if(r?.ok)u=r.user}if(!u)return formMessage('loginMsg','Логин немесе құпиясөз қате','error');currentUser=u;sessionStorage.setItem('bioCurrent',u.user);updateHeader();studentHome()}
function demoLogin(){let us=localUsers(),u=us.find(x=>x.user==='demo_student');if(!u){u={name:'Аружан Зерттеуші',class:'8А',user:'demo_student',pass:'demo',avatar:'🧬',role:'student',created:new Date().toISOString(),progress:{0:{score:100,mood:'😊',feedback:'Жасушалардың айырмашылығын түсіндім!',date:new Date().toISOString()},1:{score:100,mood:'😊',feedback:'Ұлпаларды ажырата аламын.',date:new Date().toISOString()},2:{score:100,mood:'🤔',feedback:'Полимерлер қызық екен.',date:new Date().toISOString()},3:{score:100,mood:'😊',feedback:'Липидтердің қызметін білдім.',date:new Date().toISOString()}}};us.push(u);saveUsers(us)}currentUser=u;sessionStorage.setItem('bioCurrent',u.user);updateHeader();studentHome()}
function formMessage(id,text,type){$(id).textContent=text;$(id).className='form-msg '+type}
function stats(){setGrade(userGrade());let p=gradeProgress(),vals=Object.values(p),done=vals.length,xp=done*150+(currentUser?.user==='demo_student'?50:0),avg=done?Math.round(vals.reduce((s,x)=>s+(x.score||0),0)/done):0;setTimeout(()=>{let b=document.querySelector('#student .text-btn');if(b)b.onclick=openMyLessons;if($('dailyTitle')&&done===0)$('dailyTitle').textContent=selectedGrade===7?'Экожүйе зерттеушісі':'Жасуша құпиясы'},0);return{p,vals,done,xp,avg}}
function studentHome(newAccount=false){if(!currentUser)return show('login');let s=stats(),level=Math.floor(s.xp/400)+1,names=['Жас зерттеуші','Жасуша детективі','Зертхана шебері','BIO зерттеуші','BIO LEGEND'];$('welcome').textContent=`Сәлем, ${currentUser.name.split(' ')[0]}!`;$('bigAvatar').childNodes[0].nodeValue=currentUser.avatar||'🧬';$('classLabel').textContent=currentUser.class;$('levelLabel').textContent=names[Math.min(level-1,4)];$('xp').textContent=s.xp;$('done').textContent=`${s.done}/16`;$('avg').textContent=s.avg+'%';$('progressPercent').textContent=Math.round(s.done/16*100)+'% аяқталды';$('masteryText').textContent=s.done?(s.avg>=80?'Өте жақсы нәтиже':'Тағы да сынап көр'):'Алғашқы тестті тапсыр';$('xpDelta').textContent=s.done?`+${Math.min(s.done,3)*150} XP осы аптада`:'Бастауға дайын';$('streak').textContent=Math.max(1,Math.min(s.done,7))+' күн';let x=s.xp%400;$('levelXp').textContent=`${x} / 400 XP`;$('levelBar').style.width=x/4+'%';$('nextReward').textContent=`Келесі деңгейге ${400-x} XP қалды`;renderJourney(s);renderBadges(s.done);renderWeek(s.done);$('dailyTitle').textContent=s.done?'Зерттеу сериясын үзбе!':'Жасуша құпиясы';$('dailyDesc').textContent=s.done?`Келесі «${lessons[Math.min(s.done,15)].title}» миссиясын аяқта.`:'Алғашқы зерттеуіңді баста және 150 XP жина.';$('missionBar').style.width=s.done?'65%':'0%';$('missionText').textContent=s.done?'1/2':'0/1';updateHeader();show('student');if(newAccount)setTimeout(()=>celebrate('Профиль ашылды!','Сен енді BIOLOGY FLOW зерттеушісісің.'),350)}
function renderJourney(s){let start=Math.max(0,Math.min(s.done-1,12)),ids=[start,start+1,start+2,start+3].filter((v,i,a)=>v<16&&a.indexOf(v)===i);if(ids.length<4)ids=[12,13,14,15];$('journeyMap').innerHTML=ids.map(i=>{let d=!!s.p[i],active=i===s.done;return `<article class="journey-item ${d?'done':''} ${active?'current':''}" onclick="openLesson(${i})"><div class="journey-index">${d?'✓':i+1}</div><div><small>${d?'МИССИЯ АЯҚТАЛДЫ':active?'КЕЛЕСІ МИССИЯ':'ЗЕРТТЕУ МИССИЯСЫ'}</small><h3>${lessons[i].title}</h3><span>${d?`${s.p[i].score}% • +150 XP`:active?'Қазір бастауға болады':'Маршрут бойынша жалғастыр'}</span></div><button>${d?'Қайта көру':active?'Бастау →':'🔒'}</button></article>`}).join('')}
function renderBadges(done){$('badgeCount').textContent=`${badgeDefs.filter(b=>done>=b[2]).length}/8`;$('badgeGrid').innerHTML=badgeDefs.map(b=>`<div class="badge ${done>=b[2]?'earned':''}" title="${b[1]} — ${b[2]} миссия"><span>${b[0]}</span><small>${b[1]}</small></div>`).join('')}
function renderWeek(done){let days=['Дс','Сс','Ср','Бс','Жм','Сб','Жс'],vals=[35,60,25,85,50,done?72:8,12];$('weekXp').textContent=Math.min(done,3)*150+' XP';$('weekChart').innerHTML=vals.map((v,i)=>`<div><i style="height:${v}%" class="${i===5?'today':''}"></i><small>${days[i]}</small></div>`).join('')}
function continueJourney(){openLesson(Math.min(stats().done,15))}
function chooseHypothesis(btn){btn.parentElement.querySelectorAll('button').forEach(x=>x.classList.remove('selected'));btn.classList.add('selected');stageTasks.hypothesis=true;updateStageChecks();toast('Болжам сақталды. Енді дәлел ізде! 🔎')}
function interactiveHTML(i){
  matchCount=0;selectedMatch=null;
  if(selectedGrade===11)return interactive11HTML(i);
  if(i===0)return `<div class="cell-console"><div class="console-head"><span>SPECIMEN_08</span><b>● LIVE SCAN</b></div><div class="cell-stage"><div id="cellModel" class="cell-model"><button class="organelle nucleus" onclick="organInfo(this,'Ядро','ДНҚ сақтайды және жасушаны басқарады')"><span>ЯДРО</span></button><button class="organelle mito" onclick="organInfo(this,'Митохондрия','Энергия өндіреді')"></button><button class="organelle ribo" onclick="organInfo(this,'Рибосома','Нәруыз синтездейді')"></button><i class="float-dot d1"></i><i class="float-dot d2"></i><i class="float-dot d3"></i></div><div id="organInfo" class="scanner-info"><small>НЫСАНДЫ ТАҢДА</small><b>Жасушаны сканерле</b><p>Органоидты басып, оның қызметін зертте.</p></div></div><div class="console-switch"><button class="active" onclick="toggleCell(false,this)">Эукариот</button><button onclick="toggleCell(true,this)">Прокариот</button></div></div>`;
  if(i===1)return `<div class="microscope"><div class="scope-view"><div id="tissueView" class="tissue-cells plant">${'<i></i>'.repeat(6)}</div><span id="zoomLabel">×40</span></div><div class="scope-controls"><small>VIRTUAL MICROSCOPE</small><h3 id="tissueInfo">Өсімдік жабын ұлпасы</h3><p>Препаратты ауыстырып, үлкейту мен фокусты ретте.</p><div><button class="active" onclick="setTissue('plant','Өсімдік жабын ұлпасы',this)">🌿 Өсімдік</button><button onclick="setTissue('nerve','Жүйке ұлпасы',this)">🧠 Жануар</button></div><label>Үлкейту <input type="range" min="1" max="3" value="1" oninput="zoomTissue(this.value)"></label><label>Фокус <input type="range" min="0" max="4" value="0" oninput="focusScope(this.value)"></label><button onclick="captureScope(this)">📸 Көріністі тіркеу</button></div></div>`;
  if(i===13)return diagnosisHTML();
  if(i===14)return escapeHTML(1);
  let pairs=i===7?[['🌽 Бидай','mono'],['〰️ Шашақ тамыр','mono'],['🌱 Үрмебұршақ','di'],['↧ Кіндік тамыр','di']]:i===8?[['🦋 Көбелек','arth'],['🦀 Шаян','arth'],['🐟 Балық','chord'],['🐦 Құс','chord']]:[['Ядро','structure'],['Митохондрия','structure'],['ДНҚ сақтау','function'],['Энергия өндіру','function']];
  let labels=i===7?{mono:'Даражарнақты',di:'Қосжарнақты'}:i===8?{arth:'Буынаяқтылар',chord:'Хордалылар'}:{structure:'Құрылым',function:'Қызмет'};
  return `<div class="match-game"><div class="game-status"><span>DRAG & MATCH • ${i+1}</span><b id="matchScore">0 / ${pairs.length}</b></div><p>Карточканы тиісті аймаққа сүйре. Телефонда карточканы, кейін аймақты бас.</p><div class="match-cards">${pairs.map((x,n)=>`<button id="match${n}" draggable="true" data-target="${x[1]}" ondragstart="dragMatch(event)" onclick="selectMatch(this)">${x[0]}</button>`).join('')}</div><div class="match-zones">${Object.entries(labels).map(x=>`<div data-zone="${x[0]}" ondragover="event.preventDefault()" ondrop="dropMatch(event,this)" onclick="tapMatch(this)"><b>${x[1]}</b><span>Осында орналастыр</span></div>`).join('')}</div><div id="matchFeedback" class="game-feedback">Ғылыми сәйкестікті тап 🔎</div></div>`
}
function labHTML(i){
  builderCount=0;selectedPart=null;selectedFood=null;
  if(selectedGrade===11)return lab11HTML(i);
  if(i===0)return `<div class="cell-builder"><div class="builder-head"><div><span class="kicker">CELL BUILDER</span><h3>Өсімдік жасушасын құрастыр</h3><p>Органоидты сүйреп немесе басып, атауы сәйкес орынға қой.</p></div><b id="builderScore">0/5</b></div><div class="builder-work"><div class="parts-tray">${[['🧬','Ядро','nuc'],['⚡','Митохондрия','mit'],['🌿','Хлоропласт','chl'],['💧','Вакуоль','vac'],['•','Рибосома','rib']].map((x,n)=>`<button id="part${n}" draggable="true" data-part="${x[2]}" ondragstart="dragPart(event)" onclick="selectPart(this)"><i>${x[0]}</i>${x[1]}</button>`).join('')}</div><div class="build-cell">${[['nuc','Ядро'],['mit','Митохондрия'],['chl','Хлоропласт'],['vac','Вакуоль'],['rib','Рибосома']].map(x=>`<div class="cell-slot slot-${x[0]}" data-accept="${x[0]}" ondragover="event.preventDefault()" ondrop="dropPart(event,this)" onclick="tapPart(this)"><span>${x[1]}</span></div>`).join('')}</div></div><div id="builderFeedback" class="game-feedback">Жасуша әзірге белсенді емес</div></div>`;
  if(i===3)return `<div class="food-lab"><div class="lab-shelf"><button onclick="selectFood(this,'Нан','starch')">🍞<span>Нан</span></button><button onclick="selectFood(this,'Жұмыртқа','protein')">🥚<span>Жұмыртқа</span></button><button onclick="selectFood(this,'Май','lipid')">🧈<span>Май</span></button></div><div class="lab-station"><span class="kicker">FOOD DETECTOR</span><h3 id="foodSample">Тағам үлгісін таңда</h3><div class="reagents"><button onclick="runFoodTest('starch')">🟤 Йод</button><button onclick="runFoodTest('protein')">🟣 Биурет</button><button onclick="runFoodTest('lipid')">⚪ Қағаз</button></div><div id="foodReaction" class="food-reaction"><i></i><p>Реактивті таңдағанда химиялық белгі пайда болады.</p></div></div></div>`;
  if(i===15)return `<div class="vitamin-lab"><div class="test-tubes"><button onclick="vitaminTest(this,'Лимон','жоғары',90)">🍋<i></i><small>Лимон</small></button><button onclick="vitaminTest(this,'Алма','орташа',55)">🍎<i></i><small>Алма</small></button><button onclick="vitaminTest(this,'Нан','төмен',18)">🍞<i></i><small>Нан</small></button></div><div id="vitaminResult" class="lab-result"><span class="kicker">C VITAMIN DETECTOR</span><h3>Үлгіні таңда</h3><p>Виртуалды реактив С дәруменінің салыстырмалы мөлшерін көрсетеді.</p></div></div>`;
  return `<div class="mission-lab"><div class="mission-steps"><span class="active">1. Бақылау</span><span>2. Болжам</span><span>3. Дәлел</span></div><h3>Ғалымның электронды журналы</h3><p>«${lessons[i].title}» бойынша ғылыми ойлау тізбегін құр.</p><textarea id="labNote" placeholder="Мен байқадым...&#10;Менің болжамым...&#10;Оны дәлелдейтін дерек..."></textarea><button onclick="saveLabNote(this)">Жазбаны сақтау +25 XP</button></div>`
}
function interactive11HTML(i){
  pumpNa=0;pumpK=0;flowLoaded=false;
  if(i===0)return `<div class="bio11-game antibody-game"><div class="game-status"><span>ANTIBODY LOCK • 11.4.1.1</span><b>КОМПЛЕМЕНТАРЛЫҚ</b></div><p>Антигеннің эпитопына пішіні сәйкес антиденені таңда.</p><div class="antigen-target">Антиген <i>▲</i><span id="antibodyDock">?</span></div><div class="bio11-options"><button onclick="antibodyFit(this,'●',false)">Y—●</button><button onclick="antibodyFit(this,'▲',true)">Y—▲</button><button onclick="antibodyFit(this,'■',false)">Y—■</button></div><div id="bio11Feedback" class="game-feedback">«Құлып–кілт» сәйкестігін тап.</div></div>`;
  if(i===1)return `<div class="bio11-game enzyme-game"><div class="game-status"><span>ENZYME REACTOR • 11.4.1.2</span><b id="enzymeRate">0%</b></div><div class="enzyme-stage"><span class="enzyme-shape">⚙️<i id="substrateShape">◆</i></span><div><h3>Фермент–субстрат комплексін түз</h3><label>Температура <input id="tempRange" type="range" min="0" max="70" value="10" oninput="enzymeSim()"><b id="tempValue">10°C</b></label><label>pH <input id="phRange" type="range" min="1" max="14" value="2" oninput="enzymeSim()"><b id="phValue">2</b></label><button onclick="lockEnzyme()">Комплексті түзу</button></div></div><div id="bio11Feedback" class="game-feedback">Оптимумды тап: температура 37°C, pH 7.</div></div>`;
  if(i===2)return `<div class="bio11-game"><div class="game-status"><span>INHIBITOR LAB • 11.4.1.3</span><b>САЛЫСТЫРУ</b></div><p>Ингибитор байланысқан орынға қарай оның түрін анықта.</p><div class="inhibitor-board"><div><span>Ферменттің белсенді орталығы</span><button onclick="bioChoice(this,true,'Бәсекелес ингибитор субстратпен белсенді орталық үшін бәсекелеседі.')">Ингибитор осында</button></div><div><span>Аллостериялық орталық</span><button onclick="bioChoice(this,true,'Бәсекелес емес ингибитор басқа аймаққа байланысып, фермент пішінін өзгертеді.')">Ингибитор осында</button></div></div><div id="bio11Feedback" class="game-feedback">Екі механизмді кезекпен зертте.</div></div>`;
  if(i===3)return sequenceGame('PROTEIN FACTORY • 11.4.1.4','Нәруыз биосинтезін дұрыс ретке келтір.',['ДНҚ-ның ашылуы','аРНҚ түзілуі','аРНҚ-ның рибосомаға келуі','Аминқышқыл тізбегінің жиналуы']);
  if(i===4)return `<div class="bio11-game codon-game"><div class="game-status"><span>CODON DECODER • 11.4.1.5</span><b>ГЕНЕТИКАЛЫҚ КОД</b></div><p>Бастау кодонын енгіз. Ол метионинді кодтайды.</p><div><input id="codonInput" maxlength="3" placeholder="___"><button onclick="decodeCodon()">Кодты ашу</button></div><div id="bio11Feedback" class="game-feedback">Үш нуклеотидтен тұратын кодон.</div></div>`;
  if(i===5)return `<div class="bio11-game chloroplast-game"><div class="game-status"><span>CHLOROPLAST MAP • 11.1.2.1</span><b>ҚҰРЫЛЫМ ↔ ҚЫЗМЕТ</b></div><div class="chloroplast-map"><button class="grana-hot" onclick="bioChoice(this,true,'Грана тилакоидтарында фотосинтездің жарық кезеңі жүреді.')">Грана</button><button class="stroma-hot" onclick="bioChoice(this,true,'Стромада Кальвин циклі жүріп, көмірсулар синтезделеді.')">Строма</button></div><div id="bio11Feedback" class="game-feedback">Хлоропласт бөлігін басып, қызметін аш.</div></div>`;
  if(i===6)return sequenceGame('LIGHT FLOW • 11.1.2.2','Жарық кезеңіндегі энергия ағынын құр.',['Жарық фотоны','Судың фотолизі','Электрон тасымалдау','АТФ және NADPH']);
  if(i===7)return sequenceGame('CALVIN CYCLE • 11.1.2.3','Кальвин циклінің негізгі оқиғаларын ретте.',['CO₂ фиксациясы','АТФ пен NADPH қолдану','Триоза түзілуі','RuBP регенерациясы']);
  if(i===8)return `<div class="bio11-game factor-lab"><div class="game-status"><span>PHOTOSYNTHESIS LAB • 11.1.2.4</span><b id="photoRate">0%</b></div><div class="factor-grid"><label>☀️ Жарық<input id="lightFactor" type="range" min="0" max="100" value="30" oninput="photoSim()"></label><label>☁️ CO₂<input id="co2Factor" type="range" min="0" max="100" value="30" oninput="photoSim()"></label><label>🌡️ Температура<input id="heatFactor" type="range" min="0" max="50" value="10" oninput="photoSim()"></label></div><div class="rate-graph"><i id="rateGraph"></i></div><div id="bio11Feedback" class="game-feedback">Үш факторды өзгертіп, шектеуші факторды анықта.</div></div>`;
  if(i===9)return `<div class="bio11-game"><div class="game-status"><span>ENERGY SOURCE • 11.1.2.5</span><b>САЛЫСТЫРУ</b></div><p>Органикалық зат синтезіне қолданылатын энергия көзін таңда.</p><div class="energy-duel"><button onclick="bioChoice(this,true,'Фотосинтез жарық энергиясын пайдаланады.')">☀️ Фотосинтез</button><button onclick="bioChoice(this,true,'Хемосинтез бейорганикалық заттардың тотығу энергиясын пайдаланады.')">⚗️ Хемосинтез</button></div><div id="bio11Feedback" class="game-feedback">Екі автотрофты үдерістің энергия көзін салыстыр.</div></div>`;
  if(i===10)return `<div class="bio11-game translocation-game"><div class="game-status"><span>PHLOEM FLOW • 11.1.3.1</span><b id="flowPressure">0 kPa</b></div><div class="plant-flow"><button onclick="loadSugar()">🍃 Көз: сахароза жүктеу</button><i id="flowPipe"><b></b></i><button onclick="unloadSugar()">🍎 Тұтынушы: түсіру</button></div><div id="bio11Feedback" class="game-feedback">Алдымен көзге сахароза жүктеп, қысым ағынын жаса.</div></div>`;
  if(i===11)return `<div class="bio11-game root-maze"><div class="game-status"><span>ROOT PATH • 11.1.3.2</span><b>3 ЖОЛ</b></div><p>Су өтетін бағытты басып, жолдың ерекшелігін аш.</p><div class="root-paths"><button onclick="bioChoice(this,true,'Апопласт: су жасуша қабырғалары мен жасушааралық кеңістік арқылы өтеді.')">Апопласт</button><button onclick="bioChoice(this,true,'Симпласт: су цитоплазма және плазмодесмалар арқылы өтеді.')">Симпласт</button><button onclick="bioChoice(this,true,'Вакуолярлық: су мембраналар мен вакуольдер арқылы өтеді.')">Вакуолярлық</button></div><div id="bio11Feedback" class="game-feedback">Тамыр түгінен ксилемаға жол таңда.</div></div>`;
  if(i===12)return `<div class="bio11-game membrane-game"><div class="game-status"><span>MEMBRANE GATE • 11.1.3.3</span><b id="transportEnergy">АТФ: 3</b></div><p>Затты мембранадан өткізу тәсілін таңда.</p><div class="cargo"><span>O₂: жоғары → төмен концентрация</span><button onclick="transportCargo(this,'diffusion')">Өткізу</button></div><div class="cargo"><span>Na⁺: төмен → жоғары концентрация</span><button onclick="transportCargo(this,'active')">Өткізу</button></div><div id="bio11Feedback" class="game-feedback">Градиент бағытына назар аудар.</div></div>`;
  if(i===13)return pumpGame('SODIUM–POTASSIUM PUMP • 11.1.3.4');
  if(i===14)return escape11HTML(1);
  return pumpGame('MEMBRANE RESCUE • 11.1.3.4');
}
function sequenceGame(title,prompt,steps){return `<div class="bio11-game sequence-game"><div class="game-status"><span>${title}</span><b id="sequenceScore">0/${steps.length}</b></div><p>${prompt}</p><div class="sequence-cards" data-next="0">${steps.map((s,i)=>`<button data-order="${i}" onclick="sequencePick(this,${steps.length})"><i>${i+1}</i>${s}</button>`).sort(()=>.5-Math.random()).join('')}</div><div id="bio11Feedback" class="game-feedback">Бірінші оқиғадан баста.</div></div>`}
function pumpGame(title){return `<div class="bio11-game pump-game"><div class="game-status"><span>${title}</span><b id="pumpATP">АТФ: 1</b></div><div class="membrane-line"><div><span>Жасуша іші</span><button onclick="pumpIon(this,'na')">Na⁺</button><button onclick="pumpIon(this,'na')">Na⁺</button><button onclick="pumpIon(this,'na')">Na⁺</button></div><i>МЕМБРАНА</i><div><span>Жасуша сырты</span><button onclick="pumpIon(this,'k')">K⁺</button><button onclick="pumpIon(this,'k')">K⁺</button></div></div><div id="bio11Feedback" class="game-feedback">3 Na⁺-ты сыртқа, содан кейін 2 K⁺-ты ішке тасымалда.</div></div>`}
function lab11HTML(i){if(i===5)return `<div class="pigment-lab"><span class="kicker">PIGMENT CHROMATOGRAPHY</span><h3>Пигменттерді қағазда бөл</h3><div class="chrom-paper"><i id="pigmentBand"></i></div><button onclick="runChromatography(this)">Еріткішті іске қосу</button><div id="chromResult" class="game-feedback">Пигменттердің Rf мәнін салыстыруға дайын.</div></div>`;let prompts=['Антиген мен антидене байланысын сызба түрінде сипатта.','Фермент белсенділігіне әсер ететін екі факторды жаз.','Екі ингибирлену түрінің айырмасын дәлелде.','Транскрипция мен трансляцияның орнын және өнімін салыстыр.','Генетикалық кодтың төрт қасиетін мысалмен түсіндір.','Грана мен строманың қызметін салыстыр.','Фотолиз өнімдерінің кейінгі тағдырын сипатта.','Кальвин циклінің кірісі мен шығысын жаз.','Симуляциядан шектеуші фактор туралы қорытынды жаса.','Екі үдерістің ортақ белгісі мен айырмасын жаз.','Қысым ағыны гипотезасын үш қадаммен түсіндір.','Каспари белдеуінің маңызын түсіндір.','Пассивті және белсенді тасымалды салыстыр.','Натрий–калий сорғысының потенциалға әсерін дәлелде.','Үш бөлім бойынша өзіңе қиын болған ұғымды жаз.','Сорғы жұмысы бұзылса, жасушадағы өзгерісті болжа.'];return `<div class="mission-lab"><div class="mission-steps"><span class="active">1. Бақылау</span><span>2. Талдау</span><span>3. Қорытынды</span></div><h3>11-сынып зерттеу журналы</h3><p>${prompts[i]}</p><textarea id="labNote" placeholder="Ғылыми жауабым...&#10;Дәлелім...&#10;Қорытындым..."></textarea><button onclick="saveLabNote(this)">Жазбаны сақтау +25 XP</button></div>`}
let pumpNa=0,pumpK=0,flowLoaded=false;
function antibodyFit(btn,shape,ok){document.querySelectorAll('.bio11-options button').forEach(x=>x.classList.remove('right','wrong'));btn.classList.add(ok?'right':'wrong');$('antibodyDock').textContent=shape;$('bio11Feedback').textContent=ok?'✓ Эпитоп пен антидененің вариабельді бөлігі комплементарлы. +50 XP':'Пішін сәйкес емес: бұл антидене антигенді байланыстырмайды.'}
function enzymeSim(){let t=+$('tempRange').value,p=+$('phRange').value,rate=Math.max(0,100-Math.abs(t-37)*2-Math.abs(p-7)*10);$('tempValue').textContent=t+'°C';$('phValue').textContent=p;$('enzymeRate').textContent=rate+'%';$('substrateShape').style.transform=`scale(${.7+rate/300})`;return rate}
function lockEnzyme(){let rate=enzymeSim();$('bio11Feedback').textContent=rate>90?'✓ Оптимум табылды: комплекс тұрақты түзіліп, реакция жылдам. +50 XP':'Комплекс баяу түзіледі. 37°C және pH 7 маңын тексер.'}
function bioChoice(btn,ok,text){btn.classList.add(ok?'right':'wrong');if($('bio11Feedback'))$('bio11Feedback').textContent=(ok?'✓ ':'')+text}
function sequencePick(btn,total){let box=btn.parentElement,next=+box.dataset.next,order=+btn.dataset.order;if(order===next){btn.classList.add('right');btn.disabled=true;box.dataset.next=next+1;$('sequenceScore').textContent=`${next+1}/${total}`;$('bio11Feedback').textContent=next+1===total?'🏆 Үдеріс реті толық құрылды! +50 XP':'✓ Дұрыс. Келесі кезеңді таңда.'}else{btn.classList.add('wrong');$('bio11Feedback').textContent='Бұл кезең әлі ерте. Алдыңғы оқиғаны тап.';setTimeout(()=>btn.classList.remove('wrong'),500)}}
function decodeCodon(){let code=$('codonInput').value.trim().toUpperCase().replace('T','U');$('codonInput').value=code;$('bio11Feedback').textContent=code==='AUG'?'✓ AUG — метионин және трансляцияның бастау сигналы. +50 XP':'Кодон сәйкес емес. аРНҚ-дағы бастау кодоны A әрпінен басталады.'}
function photoSim(){let l=+$('lightFactor').value,c=+$('co2Factor').value,t=+$('heatFactor').value,temp=Math.max(0,100-Math.abs(t-25)*4),rate=Math.round(Math.min(l,c,temp));$('photoRate').textContent=rate+'%';$('rateGraph').style.width=rate+'%';let factors={Жарық:l,'CO₂':c,Температура:temp},limit=Object.entries(factors).sort((a,b)=>a[1]-b[1])[0][0];$('bio11Feedback').textContent=`Шектеуші фактор: ${limit}. Ең төмен фактор жалпы жылдамдықты тежейді.`}
function loadSugar(){flowLoaded=true;$('flowPressure').textContent='120 kPa';$('flowPipe').classList.add('flowing');$('bio11Feedback').textContent='Сахароза жүктелді, су осмоспен кіріп қысым көтерілді. Енді тұтынушыда түсір.'}
function unloadSugar(){if(!flowLoaded)return $('bio11Feedback').textContent='Алдымен жапырақ-көзге сахароза жүктеу қажет.';$('flowPressure').textContent='40 kPa';$('flowPipe').classList.add('complete');$('bio11Feedback').textContent='✓ Қысым айырмасы сахарозаны көзден тұтынушыға жеткізді. +50 XP'}
function transportCargo(btn,type){btn.classList.add('right');if(type==='diffusion')$('bio11Feedback').textContent='✓ O₂ градиент бойымен қарапайым диффузия арқылы өтті — АТФ қажет емес.';else{$('transportEnergy').textContent='АТФ: 2';$('bio11Feedback').textContent='✓ Na⁺ градиентке қарсы белсенді тасымалданды — 1 АТФ жұмсалды.'}}
function pumpIon(btn,type){if(type==='na'){if(pumpNa>=3||pumpK>0)return $('bio11Feedback').textContent='Алдымен циклді ретімен орында: 3 Na⁺ сыртқа.';pumpNa++;btn.classList.add('moved')}else{if(pumpNa<3)return $('bio11Feedback').textContent='Әуелі 3 Na⁺ ионын сыртқа шығар.';pumpK++;btn.classList.add('moved')}if(pumpNa===3&&pumpK===2){$('pumpATP').textContent='АТФ: 0';$('bio11Feedback').textContent='🏆 3 Na⁺ сыртқа, 2 K⁺ ішке өтті. Мембраналық потенциал сақталды! +75 XP';toast('Натрий–калий сорғысы іске қосылды!')}else $('bio11Feedback').textContent=`Na⁺: ${pumpNa}/3 • K⁺: ${pumpK}/2`}
function runChromatography(btn){$('pigmentBand').classList.add('separated');btn.textContent='✓ Пигменттер бөлінді';$('chromResult').textContent='Хлорофилл b төменірек, хлорофилл a және каротиноидтар жоғарырақ жылжыды. Rf = пигмент жолы / еріткіш жолы.'}
function escape11HTML(stage){let tasks=[['Антидене антигеннің қай бөлігімен байланысады?',['Белсенді орталық','Эпитоп','Кодон'],1],['Жарық кезеңінің негізгі энергия өнімдері?',['АТФ және NADPH','Тек глюкоза','Тек CO₂'],0],['3 Na⁺ сыртқа шығарғанда ішке неше K⁺ кіреді?',['1','2','3'],1]],t=tasks[stage-1];return `<div class="escape-room"><div class="escape-head"><span>🔒 11-СЫНЫП BIO ESCAPE</span><b>БӨЛМЕ ${stage}/3</b></div><div class="door"><i>${stage===3?'⚡':'🧬'}</i><h3>${['Молекулалық код','Энергия шлюзі','Мембрана құлпы'][stage-1]}</h3><p>${t[0]}</p><div class="escape-options">${t[1].map((x,i)=>`<button onclick="escape11Choice(${stage},${i===t[2]})">${x}</button>`).join('')}</div><div id="escapeFeedback" class="game-feedback">Дұрыс жауап келесі бөлімді ашады.</div></div></div>`}
function escape11Choice(stage,ok){if(!ok)return $('escapeFeedback').textContent='⚠️ Қате код. Осы бөлімнің теориясын қайта талда.';if(stage<3)$('practice').innerHTML=escape11HTML(stage+1);else{$('practice').innerHTML='<div class="escape-win"><span>🏆</span><h2>11-СЫНЫП ЗЕРТХАНАСЫ АШЫЛДЫ!</h2><p>Молекула, энергия және тасымал кодтары дұрыс.</p><b>+150 XP</b></div>';celebrate('Тоқсан миссиясы орындалды!','Үш бөлімнің білімін бір жүйеге біріктірдің.')}}
let selectedMatch=null,selectedPart=null,selectedFood=null,matchCount=0,builderCount=0;
function dragMatch(e){e.dataTransfer.setData('text/plain',e.currentTarget.id)}
function selectMatch(btn){if(btn.classList.contains('matched'))return;document.querySelectorAll('.match-cards button').forEach(x=>x.classList.remove('selected'));btn.classList.add('selected');selectedMatch=btn}
function dropMatch(e,zone){e.preventDefault();matchCard($(e.dataTransfer.getData('text/plain')),zone)}
function tapMatch(zone){if(selectedMatch)matchCard(selectedMatch,zone)}
function matchCard(card,zone){if(!card||card.classList.contains('matched'))return;if(card.dataset.target===zone.dataset.zone){card.classList.add('matched');card.classList.remove('selected');zone.appendChild(card);selectedMatch=null;matchCount++;$('matchScore').textContent=`${matchCount} / 4`;$('matchFeedback').textContent=matchCount===4?'🏆 Барлық сәйкестік дұрыс! +50 XP':'✓ Дұрыс сәйкестік';if(matchCount===4)toast('DRAG & MATCH аяқталды!')}else{zone.classList.add('shake');$('matchFeedback').textContent='Бұл топқа сәйкес емес. Белгісін қайта зертте.';setTimeout(()=>zone.classList.remove('shake'),400)}}
function dragPart(e){e.dataTransfer.setData('text/plain',e.currentTarget.id)}
function selectPart(btn){if(btn.classList.contains('placed'))return;document.querySelectorAll('.parts-tray button').forEach(x=>x.classList.remove('selected'));btn.classList.add('selected');selectedPart=btn}
function dropPart(e,slot){e.preventDefault();placePart($(e.dataTransfer.getData('text/plain')),slot)}
function tapPart(slot){if(selectedPart)placePart(selectedPart,slot)}
function placePart(part,slot){if(!part||part.classList.contains('placed'))return;if(part.dataset.part===slot.dataset.accept){slot.classList.add('filled');slot.innerHTML=`<i>${part.querySelector('i').textContent}</i><span>${part.textContent.trim()}</span>`;part.classList.add('placed');selectedPart=null;builderCount++;$('builderScore').textContent=`${builderCount}/5`;$('builderFeedback').textContent=builderCount===5?'🌟 Жасуша тірілді! Барлық органоид орнында. +75 XP':'✓ Органоид дұрыс орналасты';if(builderCount===5){document.querySelector('.build-cell').classList.add('alive');toast('Өсімдік жасушасы сәтті құрастырылды!')}}else{slot.classList.add('shake');$('builderFeedback').textContent='Орны сәйкес емес. Органоид атауын салыстыр.';setTimeout(()=>slot.classList.remove('shake'),400)}}
function focusScope(v){$('tissueView').style.filter=`blur(${v}px)`;$('tissueInfo').textContent=+v===0?'Фокус дәл! Жасушалар анық көрінеді':'Көрініс бұлыңғыр — фокусты 0-ге жеткіз'}
function captureScope(btn){let blur=$('tissueView').style.filter;if(!blur||blur==='blur(0px)'){btn.textContent='✓ Көрініс тіркелді +50 XP';btn.classList.add('active');toast('Микроскопиялық бақылау сәтті!')}else toast('Алдымен фокусты дәл ретте 🔬')}
function diagnosisHTML(){return `<div class="diagnosis-game"><div class="patient"><div class="patient-avatar">🧑‍⚕️<i>!</i></div><div><span class="kicker light">CASE #014</span><h3>Пациент: Айша, 13 жас</h3><p>Белгілері: әлсіздік, қызыл иектің қанауы, жараның баяу жазылуы.</p></div></div><div class="health"><span>Денсаулық</span><i><b id="healthBar"></b></i><strong id="healthValue">35%</strong></div><h4>Қай дәрумен жетіспейді?</h4><div class="diagnosis-options"><button onclick="diagnose(this,'A')">A дәрумені</button><button onclick="diagnose(this,'C')">C дәрумені</button><button onclick="diagnose(this,'D')">D дәрумені</button></div><div id="diagnosisResult" class="game-feedback">Белгілерді талдап, диагноз қой.</div><div id="treatment" class="treatment hidden"><h4>Емдік мәзірді таңда</h4><button onclick="treatPatient(this,true)">🍋 Лимон + 🫑 бұрыш</button><button onclick="treatPatient(this,false)">🍞 Нан + 🍚 күріш</button></div></div>`}
function diagnose(btn,v){document.querySelectorAll('.diagnosis-options button').forEach(x=>x.classList.remove('right','wrong'));if(v==='C'){btn.classList.add('right');$('diagnosisResult').textContent='✓ Дұрыс: бұл — С дәрумені тапшылығы. Енді мәзір құр.';$('treatment').classList.remove('hidden')}else{btn.classList.add('wrong');$('diagnosisResult').textContent='Белгілер сәйкес келмейді. Қызыл иек пен жараның жазылуына назар аудар.'}}
function treatPatient(btn,ok){if(ok){$('healthBar').style.width='100%';$('healthValue').textContent='100%';btn.textContent='✓ Пациент құтқарылды +75 XP';btn.classList.add('right');toast('Клиникалық миссия орындалды!')}else{btn.classList.add('wrong');toast('Бұл мәзірде С дәрумені аз')}}
function escapeHTML(stage){let body=stage===1?`<p>Қауіпсіздік жүйесі: «Ядросы жоқ жасушаны анықта»</p><div class="escape-options"><button onclick="escapeChoice(1,false)">Өсімдік жасушасы</button><button onclick="escapeChoice(1,true)">Бактерия</button><button onclick="escapeChoice(1,false)">Жануар жасушасы</button></div>`:stage===2?`<p>Сканер коды: даражарнақты өсімдіктің екі белгісін таңда.</p><div class="escape-options multi"><button onclick="escapeMark(this,true)">Шашақ тамыр</button><button onclick="escapeMark(this,false)">Кіндік тамыр</button><button onclick="escapeMark(this,true)">Параллель жүйкелену</button><button onclick="escapeMark(this,false)">Торлы жүйкелену</button></div><button class="unlock-btn" onclick="checkEscapeMarks()">Кодты тексеру</button>`:`<p>Соңғы шлюз: қоректік заттар негізінен қай мүшеде сіңеді?</p><div class="escape-options"><button onclick="escapeChoice(3,false)">Асқазан</button><button onclick="escapeChoice(3,true)">Аш ішек</button><button onclick="escapeChoice(3,false)">Өңеш</button></div>`;return `<div class="escape-room"><div class="escape-head"><span>🔒 BIO ESCAPE ROOM</span><b>БӨЛМЕ ${stage}/3</b></div><div class="door"><i>${stage===3?'🔐':'🧬'}</i><h3>${stage===1?'Жасуша коды':stage===2?'Ботаникалық сканер':'Асқорыту шлюзі'}</h3>${body}<div id="escapeFeedback" class="game-feedback">Қате жауап дабылды іске қосады.</div></div></div>`}
function escapeChoice(stage,ok){if(!ok){$('escapeFeedback').textContent='⚠️ Қате код. Теориядағы дәлелдерді пайдалан.';document.querySelector('.door').classList.add('alarm');setTimeout(()=>document.querySelector('.door')?.classList.remove('alarm'),500);return}if(stage===3){$('practice').innerHTML='<div class="escape-win"><span>🏆</span><h2>ЗЕРТХАНА АШЫЛДЫ!</h2><p>Үш ғылыми код та дұрыс. BIO ESCAPE ROOM аяқталды.</p><b>+150 XP</b></div>';celebrate('Escape Room аяқталды!','Сен тоқсан білімін бір миссияда біріктірдің.')}else{$('practice').innerHTML=escapeHTML(stage+1)}}
function escapeMark(btn,correct){btn.classList.toggle('chosen');btn.dataset.correct=correct}
function checkEscapeMarks(){let chosen=[...document.querySelectorAll('.escape-options .chosen')];if(chosen.length===2&&chosen.every(x=>x.dataset.correct==='true'))$('practice').innerHTML=escapeHTML(3);else $('escapeFeedback').textContent='⚠️ Дәл екі дұрыс ботаникалық белгіні таңда.'}
function selectFood(btn,name,type){document.querySelectorAll('.lab-shelf button').forEach(x=>x.classList.remove('active'));btn.classList.add('active');selectedFood={name,type};$('foodSample').textContent=name+' үлгісі';$('foodReaction').className='food-reaction';$('foodReaction').innerHTML='<i></i><p>Енді сәйкес реактивті таңда.</p>'}
function runFoodTest(reagent){if(!selectedFood)return toast('Алдымен тағам үлгісін таңда');let ok=selectedFood.type===reagent,names={starch:'крахмал',protein:'нәруыз',lipid:'липид'};$('foodReaction').className='food-reaction '+(ok?'positive':'negative');$('foodReaction').innerHTML=`<i></i><p>${ok?'✓ Оң реакция: '+selectedFood.name+' құрамында '+names[reagent]+' анықталды. +50 XP':'Түс өзгермеді: бұл реактив басқа затты анықтайды.'}</p>`;if(ok)toast('Зертханалық реакция сәтті!')}
function organInfo(btn,title,text){document.querySelectorAll('.organelle').forEach(x=>x.classList.remove('active'));btn.classList.add('active');$('organInfo').innerHTML=`<small>СКАНЕР НӘТИЖЕСІ</small><b>${title}</b><p>${text}</p>`}
