function vitaminTest(btn,food,level,value){document.querySelectorAll('.test-tubes button').forEach(x=>x.classList.remove('active'));btn.classList.add('active');$('vitaminResult').innerHTML=`<span class="kicker">ТАЛДАУ АЯҚТАЛДЫ</span><h3>${food}: ${level} деңгей</h3><div class="result-meter"><i style="width:${value}%"></i></div><p>Салыстырмалы көрсеткіш: <b>${value}%</b></p>`}
function saveLabNote(btn){let t=$('labNote');if(!t.value.trim())return toast('Алдымен бақылауыңды жаз ✍️');btn.textContent='✓ Ғылыми жазба сақталды';btn.classList.add('saved');localStorage.setItem(`lab_${currentUser.user}_${currentLesson}`,t.value);toast('Зерттеу журналы сақталды!')}
function openLesson(i){if(!currentUser)return show('login');currentLesson=i;quizScore=null;mood='';let l=lessons[i];$('lessonNo').textContent=`МИССИЯ ${String(i+1).padStart(2,'0')} • ${selectedGrade}-СЫНЫП`;$('lessonTitle').textContent=l.title;$('lessonGoal').textContent=l.goal;$('hookQuestion').textContent=l.hook;$('hypotheses').innerHTML=['Құрылым мен қызмет байланысты','Қоршаған орта әсер етеді','Бұл кездейсоқ құбылыс'].map((x,j)=>`<button onclick="chooseHypothesis(this)"><i>${String.fromCharCode(65+j)}</i>${x}</button>`).join('');$('lessonTheory').textContent=l.theory;$('factStrip').innerHTML=l.facts.map(x=>`<span>${x}</span>`).join('');$('videoLink').href='https://www.youtube.com/results?search_query='+encodeURIComponent(`${selectedGrade} сынып биология ${l.title}`);$('practice').innerHTML=interactiveHTML(i);$('lab').innerHTML=labHTML(i);$('quiz').innerHTML=`<p class="question"><span>01</span>${l.hook}</p>${l.opts.map((o,j)=>`<label class="option"><input type="radio" name="q" value="${j}"><i>${String.fromCharCode(65+j)}</i><span>${o}</span></label>`).join('')}`;$('quizResult').innerHTML='';$('feedback').value='';document.querySelectorAll('.moods button').forEach(b=>b.classList.remove('active'));$('lessonProgressBar').style.width='20%';$('lessonProgressText').textContent='1/5 кезең';show('lesson')}
function submitQuiz(){let v=document.querySelector("input[name='q']:checked");if(!v){$('quizResult').innerHTML='<div class="result bad">Алдымен жауабыңды таңда.</div>';return null}quizScore=+v.value===lessons[currentLesson].answer?100:50;stageState.scores.end=quizScore===100?3:1;document.querySelectorAll('.option').forEach((o,j)=>{o.classList.toggle('correct',j===0);o.classList.toggle('wrong',o.querySelector('input').checked&&j!==0)});$('quizResult').innerHTML=quizScore===100?'<div class="result good"><b>Дәл таптың! 3/3 ұпай</b><span>Ғылыми дәлелің дұрыс бағытта.</span></div>':'<div class="result bad"><b>Жақсы талпыныс! 1/3 ұпай</b><span>Дұрыс жауап жасыл түспен белгіленді.</span></div>';updateStageChecks();return quizScore}
function pickMood(btn,m){mood=m;stageTasks.mood=true;document.querySelectorAll('.moods button').forEach(b=>b.classList.remove('active'));btn.classList.add('active');updateStageChecks()}
async function finishLesson(){if(quizScore===null){toast('Алдымен қорытынды сұраққа жауап бер 🧠');return document.querySelector('#quizBlock').scrollIntoView({behavior:'smooth'})}if(!mood)return toast('Сабақтан алған күйіңді таңда 😊');let total=stageState.scores.start+stageState.scores.middle+stageState.scores.end,duration=Math.max(1,Math.ceil((Date.now()-lessonStartedAt)/60000)),criteria=criteriaData(),data={score:total*10,total,stages:{start:stageState.scores.start,middle:stageState.scores.middle,end:stageState.scores.end},duration,criteria:Object.values(criteria).map(x=>x.title),feedback:$('feedback').value.trim(),mood,date:new Date().toISOString()},key=`${selectedGrade}-${currentLesson}`;if(API_URL)await api({action:'progress',user:currentUser.user,lesson:selectedGrade*100+currentLesson+1,stageStart:data.stages.start,stageMiddle:data.stages.middle,stageEnd:data.stages.end,duration:data.duration,descriptors:data.criteria.join(' | '),...data});let us=localUsers(),idx=us.findIndex(x=>x.user===currentUser.user);if(idx<0){currentUser.progress=currentUser.progress||{};currentUser.progress[key]=data}else{us[idx].progress=us[idx].progress||{};us[idx].progress[key]=data;saveUsers(us);currentUser=us[idx]}clearInterval(lessonTimer);showLessonResult(data);celebrate('Сабақ аяқталды!',`${total}/10 ұпай • +150 XP`)}
function showLessonResult(data){let level=data.total>=9?'Өте жақсы меңгерді':data.total>=7?'Жақсы меңгерді':data.total>=5?'Қосымша жұмыс қажет':'Мұғалімнің көмегі қажет',advice=data.total>=9?'Келесі сабаққа дайынсың!':data.total>=7?'Қате болған тапсырманы бір рет қайтала.':'Теория мен дескрипторларды қайта қарап шық.';document.querySelectorAll('.stage-panel').forEach(x=>x.classList.remove('active'));let p=$('lessonResultPanel');p.classList.add('active');p.innerHTML=`<div class="result-hero"><span>САБАҚ АЯҚТАЛДЫ</span><div class="result-ring" style="--score:${data.score*3.6}deg"><i><b>${data.total}/10</b><small>${data.score}%</small></i></div><h2>${level}</h2><p>${lessons[currentLesson].title}</p></div><div class="result-breakdown"><article><span>Сабақтың басы</span><b>${data.stages.start}/2</b><i><em style="width:${data.stages.start/2*100}%"></em></i></article><article><span>Сабақтың ортасы</span><b>${data.stages.middle}/5</b><i><em style="width:${data.stages.middle/5*100}%"></em></i></article><article><span>Сабақтың соңы</span><b>${data.stages.end}/3</b><i><em style="width:${data.stages.end/3*100}%"></em></i></article></div><div class="result-meta"><span>⏱️ ${data.duration} минут</span><span>${data.mood} Сабақтағы күйім</span><span>⚡ +150 XP</span></div><div class="teacher-advice"><b>Жеке ұсыныс</b><p>${advice}</p></div><div class="result-actions"><button onclick="openLesson(currentLesson)">Сабақты қайталау</button><button class="primary" onclick="studentHome()">Менің нәтижеме өту →</button></div>`;$('lessonProgressBar').style.width='100%';$('lessonProgressText').textContent='Сабақ аяқталды';document.querySelectorAll('.stage-nav button').forEach(b=>{b.classList.add('completed');b.querySelector('em').textContent='✓'});window.scrollTo({top:150,behavior:'smooth'})}
function renderTeacher(){let us=localUsers(),all=us.flatMap(u=>Object.values(u.progress||{}));$('totalStudents').textContent=us.length;$('completion').textContent=us.length?Math.round(all.length/(us.length*16)*100)+'%':'0%';$('testAverage').textContent=all.length?Math.round(all.reduce((s,p)=>s+(p.score||0),0)/all.length)+'%':'0%';$('helpSignals').textContent=all.filter(p=>p.mood==='😕').length;$('studentTable').innerHTML=us.map(u=>{let ps=Object.values(u.progress||{}),av=ps.length?Math.round(ps.reduce((s,p)=>s+(p.score||0),0)/ps.length):0,last=ps.at(-1);return `<tr><td><div class="student-cell"><span>${u.avatar||'🧬'}</span><b>${u.name}</b></div></td><td>${u.class}</td><td><div class="mini-progress"><i style="width:${ps.length/16*100}%"></i></div><small>${ps.length}/16</small></td><td><b>${ps.length*150}</b></td><td><span class="score-pill ${av>=80?'high':''}">${av}%</span></td><td>${last?last.mood+' '+(last.feedback||''):'—'}</td></tr>`}).join('')||'<tr><td colspan="6">Оқушылар әлі тіркелмеген</td></tr>';$('moodChart').innerHTML=['😊','🤔','😕'].map(m=>{let n=all.filter(p=>p.mood===m).length,p=all.length?Math.round(n/all.length*100):0;return `<div><span>${m}</span><i><b style="width:${p}%"></b></i><strong>${p}%</strong></div>`}).join('')}
function logout(){currentUser=null;sessionStorage.removeItem('bioCurrent');updateHeader();goHome()}
function toast(text){let t=$('toast');t.textContent=text;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),2600)}
function celebrate(title,text){let c=document.createElement('div');c.className='celebration';c.innerHTML=`<div class="confetti">${Array.from({length:18},(_,i)=>`<i style="--i:${i}"></i>`).join('')}</div><div><span>🏆</span><h2>${title}</h2><p>${text}</p></div>`;document.body.appendChild(c);setTimeout(()=>c.remove(),1700)}
let stageState={current:0,unlocked:0,scores:{start:0,middle:0,end:0}},stageTasks={video:false,hypothesis:false,middle:false},lessonStartedAt=0,lessonTimer=null;
function installLesson45UI(){let shell=document.querySelector('#lesson .lesson-shell');if(!shell)return;shell.innerHTML=`<aside class="stage-sidebar"><span class="kicker light">45 МИНУТТЫҚ САБАҚ</span><div class="lesson-clock"><b id="lessonClock">00:00</b><small>өткен уақыт</small></div><div class="stage-nav"><button data-stage="0" onclick="gotoStage(0)"><i>01</i><span><b>Сабақтың басы</b><small>7–10 минут</small></span><em>●</em></button><button data-stage="1" onclick="gotoStage(1)"><i>02</i><span><b>Сабақтың ортасы</b><small>25–30 минут</small></span><em>🔒</em></button><button data-stage="2" onclick="gotoStage(2)"><i>03</i><span><b>Сабақтың соңы</b><small>5–8 минут</small></span><em>🔒</em></button></div><div class="score-live"><span>Жиналған ұпай</span><b id="liveScore">0 / 10</b></div></aside><div class="lesson-content lesson45"><section id="stageStart" class="stage-panel active"><div class="stage-banner start"><span>01 • САБАҚТЫҢ БАСЫ</span><b>7–10 минут</b><h2>Қызығу және жаңа білімге қадам</h2><p>Видеоны қарап, негізгі мәселе бойынша өз болжамыңды ұсын.</p></div><div id="criteriaStart" class="criteria-card"></div><div class="video-classroom"><div class="video-screen"><span>▶</span><h3 id="videoTitle">Бейнесабақ</h3><p>Тақырып бойынша қысқа түсіндірме</p><a id="videoLink" target="_blank" rel="noopener" onclick="openVideo()">Видеоны ашу ↗</a></div><button id="videoDoneBtn" onclick="markVideoWatched()">□ Видеоны көріп болдым</button></div><div class="stage-question"><span class="kicker">БАСТАПҚЫ БОЛЖАМ</span><h2 id="hookQuestion"></h2><div id="hypotheses" class="hypotheses light-options"></div></div><div id="startChecks" class="stage-checks"></div><button id="startNextBtn" class="primary stage-next" onclick="completeStartStage()">Келесі кезеңге өту →</button></section><section id="stageMiddle" class="stage-panel"><div class="stage-banner middle"><span>02 • САБАҚТЫҢ ОРТАСЫ</span><b>25–30 минут</b><h2>Түсіну, зерттеу және қолдану</h2><p>Теорияны зерттеп, тақырыптық интерактив пен практикалық жұмысты орында.</p></div><div id="criteriaMiddle" class="criteria-card"></div><div class="lesson-block compact"><span class="kicker">НЕГІЗГІ ТҮСІНІК</span><p id="lessonTheory" class="theory-text"></p><div id="factStrip" class="fact-strip"></div></div><div class="lesson-block dark-block"><span class="kicker light">ИНТЕРАКТИВТІ ТАПСЫРМА</span><div id="practice"></div></div><div class="lesson-block"><span class="kicker">ПРАКТИКАЛЫҚ ЖҰМЫС</span><div id="lab"></div></div><div id="middleChecks" class="stage-checks"></div><button class="primary stage-next" onclick="completeMiddleStage()">Тапсырмаларды аяқтадым →</button></section><section id="stageEnd" class="stage-panel"><div class="stage-banner end"><span>03 • САБАҚТЫҢ СОҢЫ</span><b>5–8 минут</b><h2>Бағалау және қорытынды</h2><p>Біліміңді тексеріп, сабақтан алған әсеріңді белгіле.</p></div><div id="criteriaEnd" class="criteria-card"></div><div id="quizBlock" class="lesson-block quiz-block"><span class="kicker">ҚОРЫТЫНДЫ ТАПСЫРМА</span><div id="quiz"></div><button class="primary" onclick="submitQuiz()">Жауапты тексеру →</button><div id="quizResult"></div></div><div class="lesson-block exit-block"><span class="kicker">РЕФЛЕКСИЯ</span><h2>Сабақтан қандай күймен шығасың?</h2><div class="moods"><button onclick="pickMood(this,'😊')">😊<small>Түсіндім</small></button><button onclick="pickMood(this,'🤔')">🤔<small>Ойланамын</small></button><button onclick="pickMood(this,'😕')">😕<small>Көмек керек</small></button></div><textarea id="feedback" maxlength="180" placeholder="Бүгін мен үшін ең маңызды болғаны..."></textarea></div><div id="endChecks" class="stage-checks"></div><button class="primary stage-next finish-btn" onclick="finishLesson()">Нәтижені шығару ✓</button></section><section id="lessonResultPanel" class="stage-panel result-panel"></section></div>`}
function criteriaData(){let l=lessons[currentLesson],f=l.facts;return{start:{title:`${l.title} бойынша негізгі ұғымдарды анықтайды`,items:[`Бейнематериалдан ${f[0]} туралы негізгі ақпаратты табады`,`${f[0]} ұғымын таниды`,'Тақырып бойынша бастапқы болжам ұсынады'],points:2},middle:{title:`${l.title} үдерісін зерттеп, білімін қолданады`,items:[`${f[0]} мен ${f[1]} арасындағы байланысты түсіндіреді`,`${f[2]} ерекшелігін интерактивте қолданады`,'Практикалық жұмыстан дәлелді қорытынды жасайды'],points:5},end:{title:`${l.goal.replace(/^\S+\s*[–-]\s*/,'')}`,items:['Қорытынды сұраққа дұрыс жауап береді','Жауабын тақырып ұғымдарымен негіздейді','Өз оқу нәтижесіне рефлексия жасайды'],points:3}}}
function rubricHTML(label,d){return `<div class="criteria-head"><span>БАҒАЛАУ КРИТЕРИЙІ</span><b>${d.points} ұпай</b></div><h3>${d.title}</h3><div class="descriptor-list">${d.items.map((x,i)=>`<div><i>${i+1}</i><span>${x}</span><em>Дескриптор</em></div>`).join('')}</div>`}
function startLessonSession(){stageState={current:0,unlocked:0,scores:{start:0,middle:0,end:0}};stageTasks={video:false,hypothesis:false,middle:false};lessonStartedAt=Date.now();clearInterval(lessonTimer);lessonTimer=setInterval(updateLessonClock,1000);let d=criteriaData();$('criteriaStart').innerHTML=rubricHTML('Басы',d.start);$('criteriaMiddle').innerHTML=rubricHTML('Ортасы',d.middle);$('criteriaEnd').innerHTML=rubricHTML('Соңы',d.end);$('videoTitle').textContent=lessons[currentLesson].title;gotoStage(0,true);updateStageChecks()}
function updateLessonClock(){if(!$('lessonClock'))return;let sec=Math.floor((Date.now()-lessonStartedAt)/1000),m=String(Math.floor(sec/60)).padStart(2,'0'),s=String(sec%60).padStart(2,'0');$('lessonClock').textContent=`${m}:${s}`}
function gotoStage(n,force=false){if(!force&&n>stageState.unlocked)return toast('Алдымен алдыңғы кезеңді аяқта 🔒');stageState.current=n;document.querySelectorAll('.stage-panel').forEach((x,i)=>x.classList.toggle('active',i===n));document.querySelectorAll('.stage-nav button').forEach((b,i)=>{b.classList.toggle('active',i===n);b.classList.toggle('completed',i<n&&i<=stageState.unlocked);b.querySelector('em').textContent=i<stageState.unlocked?'✓':i===n?'●':'🔒'});let widths=[12,55,85,100];$('lessonProgressBar').style.width=widths[n]+'%';$('lessonProgressText').textContent=`${n+1}/3 кезең`;window.scrollTo({top:180,behavior:'smooth'})}
function openVideo(){stageTasks.videoOpened=true;$('videoDoneBtn').classList.add('ready');$('videoDoneBtn').textContent='□ Видеоны көрген соң белгіле'}
function markVideoWatched(){if(!stageTasks.videoOpened)return toast('Алдымен «Видеоны ашу» батырмасын бас');stageTasks.video=true;$('videoDoneBtn').textContent='✓ Видео қаралды';$('videoDoneBtn').classList.add('done');updateStageChecks()}
function updateStageChecks(){if(!$('startChecks'))return;$('startChecks').innerHTML=`<span class="${stageTasks.video?'done':''}">${stageTasks.video?'✓':'○'} Видео қаралды</span><span class="${stageTasks.hypothesis?'done':''}">${stageTasks.hypothesis?'✓':'○'} Болжам ұсынылды</span>`;$('middleChecks').innerHTML=`<span class="${stageTasks.middle?'done':''}">${stageTasks.middle?'✓':'○'} Интерактив пен практика аяқталды</span>`;$('endChecks').innerHTML=`<span class="${quizScore!==null?'done':''}">${quizScore!==null?'✓':'○'} Қорытынды тапсырма</span><span class="${stageTasks.mood?'done':''}">${stageTasks.mood?'✓':'○'} Рефлексия</span>`;let total=stageState.scores.start+stageState.scores.middle+stageState.scores.end;$('liveScore').textContent=`${total} / 10`}
function completeStartStage(){if(!stageTasks.video||!stageTasks.hypothesis)return toast('Видео мен бастапқы болжамды аяқта');stageState.scores.start=2;stageState.unlocked=Math.max(stageState.unlocked,1);updateStageChecks();gotoStage(1);toast('Сабақтың басы аяқталды: 2/2 ұпай')}
function completeMiddleStage(){stageTasks.middle=true;stageState.scores.middle=5;stageState.unlocked=Math.max(stageState.unlocked,2);updateStageChecks();gotoStage(2);toast('Сабақтың ортасы аяқталды: 5/5 ұпай')}
let teacherGrade=8,teacherUsers=[];
function updateHeader(){let nav=document.querySelector('.topbar nav'),hasUser=!!currentUser,isTeacher=currentUser?.role==='teacher',isStudent=hasUser&&!isTeacher;$('guestActions').classList.toggle('hidden',hasUser);$('profileButton').classList.toggle('hidden',!hasUser);if(isTeacher){nav.innerHTML='<button onclick="teacherView(\'dashboard\')">Басқару тақтасы</button><button onclick="teacherView(\'monitoring\')">Оқушылар мониторингі</button><button onclick="teacherView(\'analytics\')">Оқу аналитикасы</button><button onclick="teacherView(\'signals\')">Көмек сигналдары</button>';$('profileAvatar').textContent='👩‍🏫';$('profileName').textContent='Мұғалім';$('profileButton').onclick=()=>show('teacher')}else if(isStudent){nav.innerHTML='<button onclick="goHome()">Басты бет</button><button onclick="openMyLessons()">Сабақтарым</button><button onclick="openMyResults()">Менің нәтижем</button>';$('profileAvatar').textContent=currentUser.avatar||'🧬';$('profileName').textContent=currentUser.name.split(' ')[0];$('profileButton').onclick=studentHome}else{nav.innerHTML='<button onclick="goHome()">Басты бет</button><button onclick="openGrade(7)">7-сынып</button><button onclick="openGrade(8)">8-сынып</button>'}}
function installTeacherDashboard(){let t=$('teacher');if(!t)return;t.innerHTML=`<div class="teacher-hero"><div><span class="kicker light">BIOLOGY FLOW • TEACHER</span><h1>Сыныптың оқу пульсі</h1><p>Оқушының нәтижесін ғана емес, қай кезеңде көмек қажет екенін көріңіз.</p></div><div class="teacher-controls"><label>Сынып<select id="teacherGradeFilter" onchange="filterTeacherGrade(this.value)"><option value="8">8-сынып</option><option value="11">11-сынып</option></select></label><button onclick="exportTeacherReport()">↓ CSV есеп</button><button onclick="logout()">Шығу ↗</button></div></div><div class="teacher-stats"><article><small>ОҚУШЫЛАР</small><b id="totalStudents">0</b><span>👥</span><em id="studentTrend">Тіркелгендер</em></article><article><small>АЯҚТАЛУ ДЕҢГЕЙІ</small><b id="completion">0%</b><span>◎</span><em>1-тоқсан</em></article><article><small>ОРТАША НӘТИЖЕ</small><b id="testAverage">0%</b><span>🧠</span><em id="resultStatus">Дерек жиналуда</em></article><article class="alert-stat"><small>КӨМЕК СИГНАЛЫ</small><b id="helpSignals">0</b><span>⚠️</span><em>Назар аудару қажет</em></article></div><section id="teacher-dashboard" class="teacher-view active"><div class="teacher-overview"><article class="dashboard-card overview-progress"><div class="card-heading"><div><span class="kicker">ЖАЛПЫ КӨРІНІС</span><h2>Тоқсандық прогресс</h2></div><span class="live-dot">● LIVE</span></div><div class="overview-body"><div id="classProgressRing" class="class-ring" style="--class-score:0deg"><i><b id="classProgressValue">0%</b><small>аяқталды</small></i></div><div id="progressLegend" class="progress-legend"></div></div></article><article class="dashboard-card"><div class="card-heading"><div><span class="kicker">СОҢҒЫ ӘРЕКЕТТЕР</span><h2>Сынып лентасы</h2></div><small>Бүгін</small></div><div id="activityFeed" class="activity-feed"></div></article></div><div class="teacher-overview lower"><article class="dashboard-card"><span class="kicker">КЕЗЕҢДЕР БОЙЫНША</span><h2>Сабақтың орындалуы</h2><div id="stageAnalytics" class="stage-analytics"></div></article><article class="dashboard-card"><span class="kicker">СЫНЫП КҮЙІ</span><h2>Эмоциялық карта</h2><div id="moodChart" class="mood-chart"></div></article></div></section><section id="teacher-monitoring" class="teacher-view"><div class="dashboard-card"><div class="card-heading"><div><span class="kicker">ОҚУШЫЛАР МОНИТОРИНГІ</span><h2>Жеке нәтижелер</h2></div><input id="studentSearch" class="student-search" placeholder="Оқушыны іздеу..." oninput="filterStudentTable(this.value)"></div><div class="tablewrap"><table><thead><tr><th>Оқушы</th><th>Сынып</th><th>Сабақ</th><th>XP</th><th>Орташа</th><th>Уақыт</th><th>Соңғы белгі</th></tr></thead><tbody id="studentTable"></tbody></table></div></div></section><section id="teacher-analytics" class="teacher-view"><div class="dashboard-card"><div class="card-heading"><div><span class="kicker">ОҚУ АНАЛИТИКАСЫ</span><h2>Сабақтар бойынша меңгеру картасы</h2></div><small>Қанық түс — жоғары нәтиже</small></div><div id="lessonHeatmap" class="lesson-heatmap"></div></div><div class="analytics-grid"><article class="dashboard-card"><span class="kicker">КҮШТІ ТАҚЫРЫПТАР</span><div id="strongTopics" class="topic-list"></div></article><article class="dashboard-card"><span class="kicker">ДАМЫТУ ҚАЖЕТ</span><div id="weakTopics" class="topic-list weak"></div></article></div></section><section id="teacher-signals" class="teacher-view"><div class="signals-head"><div><span class="kicker">ПЕДАГОГИКАЛЫҚ ҚОЛДАУ</span><h2>Көмек қажет оқушылар</h2><p>70%-дан төмен нәтиже немесе «Көмек керек» рефлексиясы автоматты белгіленеді.</p></div><span id="signalCount" class="signal-count">0 сигнал</span></div><div id="signalList" class="signal-list"></div></section><div id="teacherModal" class="teacher-modal hidden"></div>`}
function teacherView(view){if(currentUser?.role!=='teacher')return show('login');show('teacher');document.querySelectorAll('.teacher-view').forEach(x=>x.classList.remove('active'));let p=$('teacher-'+view);if(p)p.classList.add('active');document.querySelectorAll('.topbar nav button').forEach(b=>b.classList.toggle('active',b.getAttribute('onclick')?.includes(view)))}
function filterTeacherGrade(g){teacherGrade=Number(g);renderTeacherData()}
function progressByGrade(u,g){let p={};Object.entries(u.progress||{}).forEach(([k,v])=>{if(k.startsWith(g+'-'))p[Number(k.split('-')[1])]=v;else if(g===8&&/^\d+$/.test(k))p[Number(k)]=v});return p}
function serverStudents(rows){return rows.map(u=>{let p={};(u.progress||[]).forEach(r=>{let n=Number(r[1]),key=n>100?Math.floor(n/100)+'-'+(n%100-1):String(n-1);p[key]={score:Number(r[2]),mood:r[3],feedback:r[4],date:r[5],stages:{start:Number(r[6]||0),middle:Number(r[7]||0),end:Number(r[8]||0)},duration:Number(r[9]||0)}});return{...u,progress:p}})}
async function renderTeacher(){teacherUsers=localUsers();renderTeacherData();if(API_URL){let r=await api({action:'dashboard'});if(r?.ok&&r.students){teacherUsers=serverStudents(r.students);renderTeacherData()}}}
function renderTeacherData(){let curriculum=teacherGrade===7?lessons7:lessons8,us=teacherUsers.filter(u=>parseInt(u.class)===teacherGrade),records=us.flatMap(u=>Object.values(progressByGrade(u,teacherGrade))),done=records.length,completion=us.length?Math.round(done/(us.length*16)*100):0,avg=done?Math.round(records.reduce((s,p)=>s+(p.score||0),0)/done):0,signals=[];us.forEach(u=>Object.entries(progressByGrade(u,teacherGrade)).forEach(([i,p])=>{if((p.score||0)<70||p.mood==='😕')signals.push({u,i:Number(i),p})}));$('totalStudents').textContent=us.length;$('completion').textContent=completion+'%';$('testAverage').textContent=avg+'%';$('helpSignals').textContent=signals.length;$('signalCount').textContent=signals.length+' сигнал';$('resultStatus').textContent=avg>=85?'Жоғары деңгей':avg>=70?'Тұрақты нәтиже':'Қолдау қажет';$('classProgressValue').textContent=completion+'%';$('classProgressRing').style.setProperty('--class-score',completion*3.6+'deg');let completed=us.filter(u=>Object.keys(progressByGrade(u,teacherGrade)).length===16).length,active=us.filter(u=>Object.keys(progressByGrade(u,teacherGrade)).length>0&&Object.keys(progressByGrade(u,teacherGrade)).length<16).length;$('progressLegend').innerHTML=`<div><i class="green-dot"></i><span>Аяқтаған</span><b>${completed}</b></div><div><i class="purple-dot"></i><span>Жалғастыруда</span><b>${active}</b></div><div><i class="gray-dot"></i><span>Бастамаған</span><b>${us.length-completed-active}</b></div>`;renderActivity(us,curriculum);renderStages(records);renderMood(records);renderStudents(us);renderHeatmap(us,curriculum);renderSignals(signals,curriculum)}
function renderActivity(us,curriculum){let a=[];us.forEach(u=>Object.entries(progressByGrade(u,teacherGrade)).forEach(([i,p])=>a.push({u,i:Number(i),p})));a.sort((x,y)=>new Date(y.p.date)-new Date(x.p.date));$('activityFeed').innerHTML=a.slice(0,5).map(x=>`<div><span>${x.u.avatar||'🧬'}</span><p><b>${x.u.name}</b><small>${curriculum[x.i]?.title||'Сабақ'} • ${x.p.score||0}%</small></p><time>${formatDate(x.p.date)}</time></div>`).join('')||'<div class="empty-state">Әзірге әрекет тіркелмеді</div>'}
function formatDate(d){if(!d)return '—';let x=new Date(d);return isNaN(x)?'—':x.toLocaleDateString('kk-KZ',{day:'2-digit',month:'2-digit'})}
function renderStages(records){let keys=[['start','Сабақтың басы',2],['middle','Сабақтың ортасы',5],['end','Сабақтың соңы',3]];$('stageAnalytics').innerHTML=keys.map(([k,n,max])=>{let v=records.length?Math.round(records.reduce((s,p)=>s+(p.stages?.[k]||0),0)/(records.length*max)*100):0;return `<div><span>${n}</span><i><b style="width:${v}%"></b></i><strong>${v}%</strong></div>`}).join('')}
function renderMood(records){$('moodChart').innerHTML=['😊','🤔','😕'].map(m=>{let n=records.filter(p=>p.mood===m).length,v=records.length?Math.round(n/records.length*100):0;return `<div><span>${m}</span><i><b style="width:${v}%"></b></i><strong>${v}%</strong></div>`}).join('')}
function renderStudents(us){$('studentTable').innerHTML=us.map(u=>{let p=Object.values(progressByGrade(u,teacherGrade)),avg=p.length?Math.round(p.reduce((s,x)=>s+(x.score||0),0)/p.length):0,dur=p.reduce((s,x)=>s+(x.duration||0),0),last=p.at(-1);return `<tr data-name="${u.name.toLowerCase()}"><td><button class="student-cell student-open" onclick="openStudentInsight('${u.user}')"><span>${u.avatar||'🧬'}</span><b>${u.name}</b></button></td><td>${u.class}</td><td><div class="mini-progress"><i style="width:${p.length/16*100}%"></i></div><small>${p.length}/16</small></td><td><b>${p.length*150}</b></td><td><span class="score-pill ${avg>=80?'high':''}">${avg}%</span></td><td>${dur||'—'} мин</td><td>${last?last.mood+' '+(last.feedback||''):'—'}</td></tr>`}).join('')||'<tr><td colspan="7">Бұл сыныпта оқушы әлі тіркелмеген</td></tr>'}
function renderHeatmap(us,curriculum){let rows=curriculum.map((l,i)=>{let values=us.map(u=>progressByGrade(u,teacherGrade)[i]).filter(Boolean),avg=values.length?Math.round(values.reduce((s,p)=>s+(p.score||0),0)/values.length):0;return{l,i,avg,count:values.length}});$('lessonHeatmap').innerHTML=rows.map(x=>`<button style="--heat:${x.avg/100}" title="${x.l.title}: ${x.avg}%"><i>${x.i+1}</i><span>${x.l.title}</span><b>${x.count?x.avg+'%':'—'}</b></button>`).join('');let ranked=rows.filter(x=>x.count).sort((a,b)=>b.avg-a.avg);$('strongTopics').innerHTML=(ranked.slice(0,3).map(x=>`<div><span>${x.i+1}</span><p>${x.l.title}</p><b>${x.avg}%</b></div>`).join('')||'<p class="empty-state">Дерек жиналуда</p>');$('weakTopics').innerHTML=(ranked.slice(-3).reverse().map(x=>`<div><span>${x.i+1}</span><p>${x.l.title}</p><b>${x.avg}%</b></div>`).join('')||'<p class="empty-state">Дерек жиналуда</p>')}
function renderSignals(signals,curriculum){$('signalList').innerHTML=signals.map(x=>`<article><span class="signal-avatar">${x.u.avatar||'🧬'}</span><div><small>${x.u.class} • ${Number(x.i)+1}-сабақ</small><h3>${x.u.name}</h3><p>${curriculum[x.i]?.title||''}</p><em>${x.p.mood==='😕'?'Оқушы «Көмек керек» деп белгіледі':'Нәтиже 70%-дан төмен'}</em></div><b>${x.p.score||0}%</b><button onclick="openStudentInsight('${x.u.user}')">Толығырақ →</button></article>`).join('')||'<div class="no-signals"><span>✓</span><h3>Қазір көмек сигналы жоқ</h3><p>Сынып нәтижелері тұрақты.</p></div>'}
function filterStudentTable(q){document.querySelectorAll('#studentTable tr').forEach(r=>r.classList.toggle('hidden',!(r.dataset.name||'').includes(q.toLowerCase())))}
function openStudentInsight(user){let u=teacherUsers.find(x=>x.user===user);if(!u)return;let p=Object.values(progressByGrade(u,teacherGrade)),avg=p.length?Math.round(p.reduce((s,x)=>s+(x.score||0),0)/p.length):0,last=p.at(-1),m=$('teacherModal');m.classList.remove('hidden');m.innerHTML=`<div><button class="modal-close" onclick="$('teacherModal').classList.add('hidden')">×</button><div class="student-profile-head"><span>${u.avatar||'🧬'}</span><div><small>${u.class} СЫНЫП</small><h2>${u.name}</h2></div></div><div class="student-modal-stats"><article><small>ПРОГРЕСС</small><b>${p.length}/16</b></article><article><small>ОРТАША</small><b>${avg}%</b></article><article><small>XP</small><b>${p.length*150}</b></article></div><h3>Соңғы сабақ нәтижесі</h3><p>${last?`${last.score}% • ${last.duration||'—'} минут • ${last.mood}`:'Сабақ әлі аяқталмаған'}</p><div class="teacher-advice"><b>Мұғалімге белгі</b><p>${last?.feedback||'Кері байланыс жоқ'}</p></div></div>`}
function exportTeacherReport(){let us=teacherUsers.filter(u=>parseInt(u.class)===teacherGrade),rows=[['Оқушы','Сынып','Аяқталған сабақ','XP','Орташа нәтиже','Жалпы уақыт']];us.forEach(u=>{let p=Object.values(progressByGrade(u,teacherGrade)),avg=p.length?Math.round(p.reduce((s,x)=>s+(x.score||0),0)/p.length):0;rows.push([u.name,u.class,p.length,p.length*150,avg+'%',p.reduce((s,x)=>s+(x.duration||0),0)+' мин'])});let csv='\ufeff'+rows.map(r=>r.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(';')).join('\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv'})),a=document.createElement('a');a.href=url;a.download=`biology-flow-${teacherGrade}-synyp.csv`;a.click();URL.revokeObjectURL(url);toast('Сынып есебі жүктелді')}
(function(){installLesson45UI();installTeacherDashboard();$('teacherGradeFilter').innerHTML='<option value="8">8-сынып</option><option value="7">7-сынып</option>';let id=sessionStorage.getItem('bioCurrent'),u=localUsers().find(x=>x.user===id);if(u){currentUser=u;updateHeader()}else updateHeader();let n=document.querySelector('.trust-row span:first-child b'),l=document.querySelector('.trust-row span:first-child small');if(n)n.textContent='32';if(l)l.textContent='интерактивті сабақ' })();
